import{_ as a,o as s,c as e,a4 as i}from"./chunks/framework.DCsBdTIw.js";const E=JSON.parse('{"title":"公益智能扶持计划","description":"Tokeness 面向开源项目、公益项目和社会化企业提供每月 1000 万至 50 亿 tokens 的 AI 智能支持。","frontmatter":{"title":"公益智能扶持计划","description":"Tokeness 面向开源项目、公益项目和社会化企业提供每月 1000 万至 50 亿 tokens 的 AI 智能支持。"},"headers":[],"relativePath":"zh/partners/impact.md","filePath":"zh/partners/impact.md","lastUpdated":1784332800000}'),d={name:"zh/partners/impact.md"};function n(l,t,h,r,o,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="公益智能扶持计划" tabindex="-1">公益智能扶持计划 <a class="header-anchor" href="#公益智能扶持计划" aria-label="Permalink to &quot;公益智能扶持计划&quot;">​</a></h1><p>Tokeness 面向开源项目、公益项目和社会化企业开放公益智能扶持计划。入选项目可获得每月 <code>1000 万 - 50 亿</code> tokens 的 AI API 支持，用于开发、运营、知识服务、内容生产、自动化处理和公共服务场景。</p><p>公益额度以 <code>MiMo-V2.5</code> 作为基准模型核算。项目可以使用其他模型，实际消耗按 Tokeness 平台模型价格、模型权限和等价额度规则折算。</p><h2 id="支持对象" tabindex="-1">支持对象 <a class="header-anchor" href="#支持对象" aria-label="Permalink to &quot;支持对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>开源项目</td><td>面向开发者工具、基础设施、教育资源、无障碍技术、公共数据、AI 安全等方向的开源项目</td></tr><tr><td>公益项目</td><td>面向教育、医疗、环保、灾害响应、心理健康、乡村服务、弱势群体支持等领域的公益组织或公益行动</td></tr><tr><td>社会化企业</td><td>以商业方式解决社会问题的企业，例如普惠教育、助残就业、可持续消费、社区服务和公益科技</td></tr></tbody></table><h2 id="额度档位" tabindex="-1">额度档位 <a class="header-anchor" href="#额度档位" aria-label="Permalink to &quot;额度档位&quot;">​</a></h2><p>公益额度按月发放，不折现、不退款、不转售，未使用额度默认不滚存。</p><table tabindex="0"><thead><tr><th>档位</th><th style="text-align:right;">每月基准额度</th><th>适合对象</th></tr></thead><tbody><tr><td>Starter</td><td style="text-align:right;">1000 万 tokens</td><td>已有官网首页、公开仓库或项目发布页的早期项目</td></tr><tr><td>Builder</td><td style="text-align:right;">5000 万 tokens</td><td>有真实用户、社区或受益人的项目</td></tr><tr><td>Growth</td><td style="text-align:right;">1 亿 tokens</td><td>有稳定使用场景和可量化影响目标的项目</td></tr><tr><td>Impact</td><td style="text-align:right;">5 亿 tokens</td><td>服务规模较大、已有成熟运营机制的项目</td></tr><tr><td>Strategic</td><td style="text-align:right;">50 亿 tokens</td><td>高影响力基础设施、重点公益平台或联合项目</td></tr></tbody></table><p><code>Strategic</code> 档位需要单独评审，必须按周、按 Key 或按项目分批释放额度，并接受周度或月度复核。复核不通过时，Tokeness 可降低档位、暂停后续释放或调整模型范围。</p><h2 id="申请前置要求" tabindex="-1">申请前置要求 <a class="header-anchor" href="#申请前置要求" aria-label="Permalink to &quot;申请前置要求&quot;">​</a></h2><p>申请前，项目方需要先在指定公开位置添加 Tokeness 支持声明。未添加、位置不符合要求或无法公开访问的项目，不进入额度评审流程。</p><p>可放置位置按项目公开载体选择：</p><table tabindex="0"><thead><tr><th>位置</th><th>示例</th></tr></thead><tbody><tr><td>公开仓库</td><td>GitHub、Gitee、CNB 等仓库的 <code>README.md</code></td></tr><tr><td>项目官网</td><td>网站首页必须展示，建议放在首页页脚</td></tr><tr><td>无官网且无公开仓库</td><td>项目发布页底部、项目动态末尾、博客文章末尾或公众号文章末尾</td></tr></tbody></table><p>如果项目同时有官网和公开仓库，优先放在官网首页页脚或仓库 <code>README.md</code>。赞助页、合作伙伴页、文档页、二级页面或临时公告不能替代首页页脚或仓库 <code>README.md</code>。</p><p>仓库 <code>README.md</code> 推荐写法：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;p&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  本项目的 AI API 支持由</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;a href=&quot;https://tokeness.ai&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tokeness.ai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/a&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  赞助提供。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/p&gt;</span></span></code></pre></div><p>网站页脚或发布页底部写法：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本项目的 AI API 支持由</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://tokeness.ai&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_blank&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;noopener&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://docs.tokeness.ai/logo.svg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tokeness.ai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 赞助提供。</span></span></code></pre></div><p>Tokeness 会在申请审核和续期审核时检查该链接是否仍然公开可访问。未展示 Logo、未链接到 <code>https://tokeness.ai</code>、链接放置位置不符合要求，均视为未完成申请前置要求。</p><h2 id="可用能力" tabindex="-1">可用能力 <a class="header-anchor" href="#可用能力" aria-label="Permalink to &quot;可用能力&quot;">​</a></h2><p>入选项目将获得一个或多个公益专用 API Key。Tokeness 会根据项目用途配置额度、模型范围、分组和必要的限制策略。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>OpenAI 兼容接口</td><td>使用 <code>https://n.tokeness.dev/v1</code> 接入大多数支持自定义 Base URL 的工具</td></tr><tr><td>多模型调用</td><td>默认以 <code>DeepSeek-V4-Flash</code> 为额度基准，可按规则使用其他模型</td></tr><tr><td>Key 与额度控制</td><td>按项目、环境或任务拆分 Key，并设置额度上限</td></tr><tr><td>使用日志</td><td>在控制台核对请求、模型、状态和消耗</td></tr><tr><td>数据看板</td><td>观察模型调用趋势和月度消耗</td></tr></tbody></table><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to &quot;典型场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目类型</th><th>推荐场景</th></tr></thead><tbody><tr><td>开源项目</td><td>Issue 分类、PR 辅助审查、文档生成、测试用例生成、多语言翻译、贡献者问答</td></tr><tr><td>公益项目</td><td>志愿者培训、政策问答、服务对象咨询、资料整理、无障碍内容改写</td></tr><tr><td>社会化企业</td><td>用户支持、知识库问答、教育陪练、运营自动化、报告生成</td></tr></tbody></table><p>高成本模型、图片生成、长上下文、高并发批处理等场景可能需要单独说明用途，并接受更细的模型范围和额度限制。</p><h2 id="申请流程" tabindex="-1">申请流程 <a class="header-anchor" href="#申请流程" aria-label="Permalink to &quot;申请流程&quot;">​</a></h2><ol><li>在仓库 <code>README.md</code>、官网首页页脚，或无官网且无公开仓库时的项目发布页底部、项目动态末尾、博客文章末尾、公众号文章末尾添加 Tokeness 支持声明。</li><li>准备项目介绍、公开链接、使用场景、预计月度 token 需求和影响目标。</li><li>将申请材料发送至 <a href="mailto:contact@tokeness.ai" target="_blank" rel="noreferrer">contact@tokeness.ai</a>，邮件标题建议写为 <code>公益智能扶持申请 - 项目名称</code>。</li><li>Tokeness 审核项目真实性、公开鸣谢链接、额度需求和合规风险。</li><li>审核通过后，项目方注册或确认 Tokeness 账户。</li><li>Tokeness 发放公益专用 Key，并配置额度、模型范围和使用限制。</li><li>项目按月提交简短使用反馈，Tokeness 根据使用情况决定续期、升档、降档或停止支持。</li></ol><h2 id="审核标准" tabindex="-1">审核标准 <a class="header-anchor" href="#审核标准" aria-label="Permalink to &quot;审核标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th style="text-align:right;">权重</th></tr></thead><tbody><tr><td>公共价值和社会影响</td><td style="text-align:right;">30%</td></tr><tr><td>项目真实性与持续运营能力</td><td style="text-align:right;">25%</td></tr><tr><td>AI 使用场景清晰度</td><td style="text-align:right;">20%</td></tr><tr><td>额度需求合理性</td><td style="text-align:right;">15%</td></tr><tr><td>开放性、透明度或可复用价值</td><td style="text-align:right;">10%</td></tr></tbody></table><p>Tokeness 优先支持已经有真实用户、受益人、社区、仓库记录或公开服务案例的项目。</p><h2 id="使用规则" tabindex="-1">使用规则 <a class="header-anchor" href="#使用规则" aria-label="Permalink to &quot;使用规则&quot;">​</a></h2><p>公益额度仅限申请中说明的开源、公益或社会价值场景使用。</p><p>禁止行为包括：</p><ul><li>售卖、转租、转赠公益额度或 API Key。</li><li>将公益 Key 用于商业分销、代理转发或无关项目。</li><li>违法违规、侵权、欺诈、攻击、绕过风控、垃圾内容生产。</li><li>恶意消耗、异常高并发、失控重试或明显偏离申请用途的调用。</li><li>将 API Key 写入前端代码、公开仓库、截图、群聊或其他不安全位置。</li></ul><p>如出现异常请求、重大风险、上游政策变化、长期无反馈或公开鸣谢链接失效，Tokeness 可暂停、限流、调整模型范围、停止后续额度或取消公益资格。</p><h2 id="续期与反馈" tabindex="-1">续期与反馈 <a class="header-anchor" href="#续期与反馈" aria-label="Permalink to &quot;续期与反馈&quot;">​</a></h2><p>公益支持默认按月复核。项目方需要保留公开鸣谢链接，并按月反馈：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>使用情况</td><td>本月主要使用场景、调用规模和模型类型</td></tr><tr><td>影响结果</td><td>服务人数、处理任务数、节省时间、社区贡献或其他可衡量结果</td></tr><tr><td>下月计划</td><td>预计额度、模型需求和新增使用场景</td></tr></tbody></table><p>反馈充分、影响明确且使用合规的项目，可申请升级档位。长期无使用、无反馈或用途不清晰的项目，Tokeness 可降低档位或停止支持。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>申请与合作咨询：<a href="mailto:contact@tokeness.ai" target="_blank" rel="noreferrer">contact@tokeness.ai</a></p><p>服务入口：<a href="https://tokeness.ai" target="_blank" rel="noreferrer">tokeness.ai</a></p>`,42)])])}const c=a(d,[["render",n]]);export{E as __pageData,c as default};
